<div class="mb-8 flex flex-wrap items-end justify-between gap-4"><div><p class="text-[10px] font-bold uppercase tracking-[.2em] text-[#687158]">Help centre</p><h1 class="mt-2 text-3xl font-medium">Support tickets</h1><p class="mt-2 text-sm text-[#77796f]">We are here when you need us.</p></div><button class="rounded-xl bg-[#687158] px-4 py-3 text-xs font-semibold text-white" onclick="$('#ticket-modal').removeClass('hidden')">＋ New ticket</button></div><section class="overflow-hidden rounded-2xl border border-[#e5e5dd] bg-[#fbfbf7]"><div class="overflow-x-auto"><table class="customer-table w-full"><thead><tr><th>Ticket</th><th>Subject</th><th>Status</th><th>Date</th><th></th></tr></thead><tbody><?php if(!$tickets): ?><tr><td colspan="5" class="text-[#77796f]">No support tickets yet.</td></tr><?php endif; ?><?php foreach($tickets as $ticket): ?><tr><td><strong><?= e($ticket['id']) ?></strong></td><td><?= e($ticket['subject']) ?></td><td><?= customer_badge($ticket['status']) ?></td><td><?= e($ticket['date']) ?></td><td><button class="text-xs text-[#687158]" onclick="customerToast('Ticket details will open here.')">View →</button></td></tr><?php endforeach; ?></tbody></table></div></section><div id="ticket-modal" class="fixed inset-0 z-50 hidden bg-[#252820]/40 p-5"><div class="mx-auto mt-20 max-w-lg rounded-2xl bg-[#fbfbf7] p-6"><div class="mb-5 flex justify-between"><h2 class="text-lg font-medium">New support ticket</h2><button onclick="$('#ticket-modal').addClass('hidden')"><i data-lucide="x" class="h-5 w-5"></i></button></div><form id="ticket-form" class="space-y-4"><label class="block text-xs text-[#77796f]">Subject<input name="subject" class="mt-2 w-full rounded-xl border border-[#ddd] bg-transparent p-3" required></label><label class="block text-xs text-[#77796f]">Message<textarea name="message" class="mt-2 w-full rounded-xl border border-[#ddd] bg-transparent p-3" rows="4" required></textarea></label><button class="rounded-xl bg-[#687158] px-4 py-3 text-xs font-semibold text-white" type="submit">Submit ticket</button></form></div></div><script>$('#ticket-form').on('submit',function(e){e.preventDefault();$.post('<?= e(($base ?: '') . '/customer/ajax/support-ticket') ?>',$(this).serialize()).done(function(r){$('#ticket-modal').addClass('hidden');customerToast(r.message||'Ticket created.');setTimeout(()=>location.reload(),500)}).fail(function(xhr){customerToast((xhr.responseJSON||{}).message||'Could not create ticket.')})});</script>
